import React, { useState } from 'react';
import { 
  Trash2, Map, Calendar, Star, LineChart, Users, 
  HardHat, FileText, Activity, ShieldAlert, ChevronLeft, AlertCircle, Filter, Search
} from 'lucide-react';

// --- NEW COMPONENT: BIN MONITORING TAB ---
const BinMonitoringTab = () => {
  const binData = [
    { id: 'BN-401', zone: 'North Sector', capacity: 85, health: 'Good', status: 'Active', code: 'T2T-01' },
    { id: 'BN-402', zone: 'Central Park', capacity: 32, health: 'Needs Cleaning', status: 'Active', code: 'T2T-02' },
    { id: 'BN-403', zone: 'Industrial Area', capacity: 98, health: 'Sensor Error', status: 'Warning', code: 'T2T-03' },
    { id: 'BN-404', zone: 'South Wharf', capacity: 12, health: 'Good', status: 'Offline', code: 'T2T-04' },
    { id: 'BN-405', zone: 'West Plaza', capacity: 65, health: 'Good', status: 'Active', code: 'T2T-05' },
    { id: 'BN-406', zone: 'East Gate', capacity: 45, health: 'Good', status: 'Active', code: 'T2T-06' },
  ];

  return (
    <div className="w-full animate-slot flex flex-col gap-6">
      {/* MODULE TOOLBAR */}
      <div className="flex flex-wrap items-center justify-between gap-4 bg-[#A1AED1] p-4 border-[6px] border-[#47510B] rounded-2xl shadow-[4px_4px_0_0_#47510B]">
        <div className="flex items-center gap-3">
          <Trash2 size={24} className="text-[#AB1717]" />
          <h2 className="text-xl font-black italic text-[#47510B] uppercase tracking-tighter">01_BIN_TELEMETRY</h2>
        </div>
        <div className="flex gap-2">
          <div className="relative">
            <Search className="absolute left-2 top-1.5 text-[#47510B] opacity-50" size={14} />
            <input type="text" placeholder="SEARCH_ID..." className="bg-[#FDFAD8] border-2 border-[#47510B] pl-8 pr-3 py-1 text-[10px] font-black rounded-lg focus:outline-none w-32 md:w-48" />
          </div>
          <div className="bg-[#CAD23C] p-1.5 rounded-lg border-2 border-[#47510B] cursor-pointer hover:bg-[#FDFAD8] transition-colors">
            <Filter size={16} />
          </div>
        </div>
      </div>

      {/* BIN CARDS GRID */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {binData.map((bin) => (
          <div key={bin.id} className="bg-white border-[6px] border-[#47510B] rounded-[30px] p-5 shadow-[8px_8px_0_0_#A1AED1] hover:translate-y-[-4px] transition-all relative overflow-hidden">
            {/* Background Accent */}
            <div className="absolute top-0 left-0 w-full h-1 bg-[#47510B]/10" />

            <div className="flex justify-between items-start mb-4">
              <div>
                <span className="text-[8px] font-black text-[#AB1717] tracking-[0.3em] uppercase opacity-60">Node_ID</span>
                <h3 className="text-xl font-black text-[#47510B] leading-none mt-1 italic">{bin.id}</h3>
              </div>
              <div className={`flex items-center gap-2 px-2 py-1 border-2 border-[#47510B] rounded-md text-[8px] font-black ${
                bin.status === 'Active' ? 'bg-[#CAD23C]/20 text-[#47510B]' : 'bg-[#AB1717]/20 text-[#AB1717]'
              }`}>
                <div className={`w-2 h-2 rounded-full ${bin.status === 'Active' ? 'bg-[#CAD23C] animate-pulse' : 'bg-[#AB1717]'}`} />
                {bin.status.toUpperCase()}
              </div>
            </div>

            {/* CAPACITY METER */}
            <div className="mb-6">
              <div className="flex justify-between text-[10px] font-black uppercase mb-1.5">
                <span className="tracking-widest opacity-70">Capacity_Load</span>
                <span className={bin.capacity > 85 ? 'text-[#AB1717]' : 'text-[#47510B]'}>{bin.capacity}%</span>
              </div>
              <div className="w-full h-5 bg-[#FDFAD8] border-[3px] border-[#47510B] rounded-full overflow-hidden shadow-inner">
                <div 
                  className={`h-full transition-all duration-1000 border-r-2 border-[#47510B] ${bin.capacity > 85 ? 'bg-[#AB1717]' : 'bg-[#CAD23C]'}`}
                  style={{ width: `${bin.capacity}%` }}
                />
              </div>
            </div>

            {/* STATS TABLE */}
            <div className="grid grid-cols-2 gap-y-3 gap-x-4 border-t-2 border-[#47510B]/10 pt-4">
              <div className="flex flex-col">
                <span className="text-[8px] font-black uppercase opacity-40 text-[#47510B]">Sector</span>
                <span className="text-[10px] font-bold text-[#47510B] truncate tracking-tighter">{bin.zone}</span>
              </div>
              <div className="flex flex-col">
                <span className="text-[8px] font-black uppercase opacity-40 text-[#47510B]">Health_Index</span>
                <span className={`text-[10px] font-bold ${bin.health !== 'Good' ? 'text-[#AB1717]' : 'text-[#47510B]'}`}>{bin.health}</span>
              </div>
              <div className="flex flex-col">
                <span className="text-[8px] font-black uppercase opacity-40 text-[#47510B]">System_Code</span>
                <span className="text-[10px] font-mono font-bold italic text-[#47510B]">{bin.code}</span>
              </div>
              <button className="bg-[#47510B] text-[#CAD23C] text-[8px] font-black rounded-lg py-2 hover:bg-[#AB1717] hover:text-[#FDFAD8] transition-all shadow-[2px_2px_0_0_#CAD23C] active:shadow-none active:translate-y-0.5">
                ACCESS_LOGS
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

const Dashboard = () => {
  const [currentView, setCurrentView] = useState('MENU');

  const allTabs = [
    { id: 'BINS', label: '01_BIN_MONITORING', icon: <Trash2 size={32}/> },
    { id: 'ZONES', label: '02_AREAS_&_ZONES', icon: <Map size={32}/> },
    { id: 'SCHEDULE', label: '03_COLL_SCHEDULE', icon: <Calendar size={32}/> },
    { id: 'POINTS', label: '04_REWARDS_POINTS', icon: <Star size={32}/> },
    { id: 'ANALYTICS', label: '05_SYS_ANALYTICS', icon: <LineChart size={32}/> },
    { id: 'CITIZENS', label: '06_CITIZEN_INFO', icon: <Users size={32}/> },
    { id: 'WORKERS', label: '07_WORKER_NODES', icon: <HardHat size={32}/> },
    { id: 'REPORTS', label: '08_SYS_REPORTS', icon: <FileText size={32}/> },
  ];

  // --- RENDERING LOGIC ---
  const renderContent = () => {
    if (currentView === 'MENU') {
      return (
        <div className="w-full bg-[#A1AED1] border-[8px] border-[#47510B] rounded-[40px] p-6 md:p-10 yellow-stack-shadow animate-slot">
          <p className="text-xs font-black uppercase tracking-[0.3em] text-[#AB1717] mb-8 ml-2">Select_Operational_Node</p>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {allTabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setCurrentView(tab.id)}
                className="group relative flex flex-col items-center justify-center gap-4 p-8 rounded-[30px] border-[6px] border-[#47510B] bg-[#FDFAD8] transition-all hover:-translate-y-2 hover:bg-[#CAD23C] active:translate-y-1 shadow-[0_12px_0_0_#47510B] hover:shadow-[0_4px_0_0_#47510B]"
              >
                <div className="text-[#AB1717] group-hover:text-[#47510B] transition-transform group-hover:scale-110">
                  {tab.icon}
                </div>
                <span className="text-xs font-[1000] uppercase tracking-tighter text-[#47510B] text-center leading-tight">
                  {tab.label.replace(/_/g, ' ')}
                </span>
                <div className="absolute top-4 right-4 w-3 h-3 rounded-full bg-[#47510B] border-2 border-[#AB1717]/20 group-hover:bg-[#AB1717]" />
              </button>
            ))}
          </div>
        </div>
      );
    }

    // IF VIEW IS BINS, SHOW THE NEW TAB
    if (currentView === 'BINS') {
      return (
        <div className="w-full flex flex-col gap-6">
          <button onClick={() => setCurrentView('MENU')} className="flex items-center gap-2 bg-[#47510B] text-[#FDFAD8] px-6 py-3 rounded-2xl font-black uppercase text-xs w-fit hover:bg-[#AB1717] transition-all shadow-[4px_4px_0_0_#CAD23C]">
            <ChevronLeft size={20} /> Back_to_Console
          </button>
          <BinMonitoringTab />
        </div>
      );
    }

    // PLACEHOLDER FOR OTHER TABS
    return (
      <div className="w-full flex flex-col gap-6">
        <button onClick={() => setCurrentView('MENU')} className="flex items-center gap-2 bg-[#47510B] text-[#FDFAD8] px-6 py-3 rounded-2xl font-black uppercase text-xs w-fit hover:bg-[#AB1717] transition-all shadow-[4px_4px_0_0_#CAD23C]">
          <ChevronLeft size={20} /> Back_to_Console
        </button>
        <div className="bg-white border-[8px] border-[#47510B] rounded-[40px] p-12 md:p-20 text-center flex flex-col items-center justify-center shadow-2xl min-h-[500px]">
          <AlertCircle size={80} className="text-[#AB1717] mb-6 animate-pulse" />
          <h2 className="text-4xl md:text-6xl font-black italic text-[#47510B] uppercase tracking-tighter mb-4">{currentView}</h2>
          <p className="text-sm font-bold text-[#47510B] opacity-50 uppercase tracking-[0.5em]">Awaiting_Module_Design</p>
        </div>
      </div>
    );
  };

  return (
    <div className="w-full min-h-screen bg-[#FDFAD8] p-4 md:p-8 flex items-center justify-center font-sans overflow-x-hidden">
      <div className="w-full max-w-[1200px] flex flex-col gap-8">

        {/* HEADER */}
        <div className="bg-[#AB1717] border-[8px] border-[#47510B] rounded-t-[50px] rounded-b-[20px] p-6 md:p-8 red-stack-shadow shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4 md:gap-6">
              <div className="bg-[#FDFAD8] p-3 rounded-2xl border-4 border-[#47510B] shadow-[5px_5px_0_0_#47510B]">
                <ShieldAlert size={32} className="text-[#AB1717]" strokeWidth={2.5} />
              </div>
              <div>
                <p className="text-[10px] font-black uppercase tracking-[0.4em] text-[#FDFAD8] opacity-60 italic mb-1">Command.Master.Console</p>
                <h1 className="text-2xl md:text-5xl font-black italic text-[#FDFAD8] uppercase tracking-tighter leading-none">
                  TRASH<span className="text-[#CAD23C]">2</span>TRACK
                </h1>
              </div>
            </div>
            <Activity className="text-[#CAD23C] animate-pulse" size={32} />
          </div>
        </div>

        {/* CONTENT AREA */}
        {renderContent()}

        {/* FOOTER */}
        <div className="flex flex-col items-center gap-2 opacity-40 py-4">
            <div className="w-full h-1 bg-[#47510B]/20 rounded-full mb-2" />
            <p className="text-[9px] font-black uppercase tracking-[1em] text-[#47510B] text-center">Secure.Industrial.Admin.Terminal.v3.0</p>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
